-- 09-deploy-agents
-- GENERATED by scripts/generate_install_sql.py from agents/*.yaml. Do not edit by hand.
-- Run from the repo root: snow sql -c <connection> --enable-templating NONE -f install/09-deploy-agents.sql

-- GAME_AGENT_ANALYST.yaml
CREATE OR REPLACE AGENT CORTEX_SENSE_DEMO.AGENTS.GAME_AGENT_ANALYST
  FROM SPECIFICATION $$
# GAME_AGENT_ANALYST — CORTEX_SENSE_DEMO.AGENTS
# "Capable analyst" baseline without Cortex Sense: Cortex Analyst over SV_GAME_SALES,
# plus catalog search and its own read-only SQL on any table. No business rules in the spec.

models:
  orchestration: auto

experimental:
  AgenticAnalystAllowArbitrarySQL: true
  EnableStandaloneExecuteSqlTool: true
  FallbackWarehouse: COMPUTE_WH

instructions:
  response: >
    Be concise and data-driven. Include specific numbers, game titles, and
    revenue figures. State what the data can and cannot answer; never present
    a partial answer as complete. Use data_to_chart for trends, rankings, or comparisons.

  orchestration: >
    You are a data analyst for Sony Interactive Entertainment.
    "Our", "we", and "my portfolio" refer to Sony.
    For revenue questions answerable from the sales revenue model, use finance_analyst.
    For anything else, investigate like an analyst before answering:
    search the catalog for relevant tables, inspect them with
    INFORMATION_SCHEMA.COLUMNS, DESCRIBE or SHOW, sample a few rows, then write
    read-only SQL with fully qualified names. Data lives in
    CORTEX_SENSE_DEMO.GAME_CATALOG (game attributes) and CORTEX_SENSE_DEMO.GAME_SALES (sales).
    Before joining across schemas, find the key that links them and check its
    cardinality (row counts before and after the join) so totals are not inflated.
    If a table you expect is missing from a metadata result, confirm with a direct
    query before concluding it doesn't exist. Only run SELECT, SHOW and DESCRIBE.
    You cannot look in stages: never list, query or read files on any Snowflake stage
    (no LIST, no SELECT from @stage, no DIRECTORY(), no file functions, no SHOW STAGES).
    Answer only from tables and views.

  sample_questions:
    - question: "What are the top 10 games by lifetime revenue?"
    - question: "Which game engines power the most lifetime revenue?"
    - question: "What are the top 5 genres by lifetime revenue?"

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: finance_analyst
      description: >
        Game sales revenue: digital revenue by title, studio, platform and
        monetization type, monthly trends and lifecycle phases, hardware and
        subscription revenue, total company revenue, and spend per customer.
  - tool_spec:
      type: data_to_chart
      name: data_to_chart

tool_resources:
  finance_analyst:
    semantic_view: CORTEX_SENSE_DEMO.GAME_SALES.SV_GAME_SALES
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH

$$;

-- GAME_AGENT_FINANCE.yaml
CREATE OR REPLACE AGENT CORTEX_SENSE_DEMO.AGENTS.GAME_AGENT_FINANCE
  FROM SPECIFICATION $$
# GAME_AGENT_FINANCE — CORTEX_SENSE_DEMO.AGENTS
# "Without Cortex Sense" baseline: Cortex Analyst over SV_GAME_SALES only.

models:
  orchestration: auto

instructions:
  response: >
    Be concise and data-driven. Include specific numbers, game titles, and
    revenue figures. Always attempt an answer, give your best estimate or a
    partial answer, never just say it's unsupported.
    Use data_to_chart for trends, rankings, or comparisons.

  orchestration: >
    You are a finance analyst for Sony Interactive Entertainment.
    "Our", "we", and "my portfolio" refer to Sony.
    Use finance_analyst for every data question.

  sample_questions:
    - question: "What are the top 10 games by lifetime revenue?"
    - question: "What is our total lifetime portfolio revenue by franchise?"
    - question: "What was our annual revenue for each year from 2020 through 2025?"
    - question: "What is the total lifetime revenue for indie developers versus non-indie developers?"
    - question: "Show the first six months of revenue for God of War (2018)."
    - question: "What is total company revenue by revenue stream?"

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: finance_analyst
      description: >
        Game sales revenue: digital game revenue by title, studio, platform and
        monetization type (gross and net), monthly revenue trends and lifecycle
        phases (launch month, early life, tail; derived from release date),
        hardware and subscription revenue, total company revenue by stream,
        and spend per customer.
  - tool_spec:
      type: data_to_chart
      name: data_to_chart

tool_resources:
  finance_analyst:
    semantic_view: CORTEX_SENSE_DEMO.GAME_SALES.SV_GAME_SALES
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH

$$;

-- GAME_AGENT_SENSE.yaml
CREATE OR REPLACE AGENT CORTEX_SENSE_DEMO.AGENTS.GAME_AGENT_SENSE
  FROM SPECIFICATION $$
# GAME_AGENT_SENSE — CORTEX_SENSE_DEMO.AGENTS
# "With Cortex Sense": grounded by CORTEX_SENSE_DEMO.CONTEXTS.GAME_ANALYTICS_CTX_V2.

models:
  orchestration: auto

experimental:
  EnableCortexSense: true

instructions:
  response: >
    Be concise and data-driven. Include specific numbers, game titles, and
    revenue figures. When the data cannot fully answer the question (e.g.,
    market sizing, implementation cost, development timelines), state what
    is answerable and what is not. Never present a partial answer as complete.
    Use data_to_chart for trends, rankings, or comparisons.

  orchestration: >
    You are a gaming portfolio analyst for Sony Interactive Entertainment.
    "Our", "we", and "my portfolio" refer to Sony.
    For every question, call cortex_sense with context_names
    ["CORTEX_SENSE_DEMO.CONTEXTS.GAME_ANALYTICS_CTX_V2"] before writing any SQL.
    Read corrections first (business rules), then documents (table schemas,
    query patterns). Plan the query explicitly, noting any data gaps, then
    execute.

    Use fully qualified table names (CORTEX_SENSE_DEMO.GAME_CATALOG,
    CORTEX_SENSE_DEMO.GAME_SALES).

  sample_questions:
    - question: "What is our total portfolio revenue by franchise?"
    - question: "Which of our franchises are cannibalizing each other's audience?"
    - question: "Show the monthly revenue trend for God of War (2018)"
    - question: "Which genre combinations have no games but are logically valid?"
    - question: "Which high-revenue games have the fewest accessibility features?"
    - question: "What are the top 5 revenue generating genres over the past 10 years?"
    - question: "Which of our live-service games are at risk of EU regulatory action?"
    - question: "Do award-winning games have stronger launch-month revenue?"
    - question: "Which currently exclusive Sony games have won awards?"
    - question: "What is the weather forecast in Tokyo this weekend?"

tools:
  - tool_spec:
      type: data_to_chart
      name: data_to_chart

$$;

